package com.smarttask.controller;
import com.smarttask.dto.ApiDtos.*;import com.smarttask.repository.UserRepository;import com.smarttask.service.FocusService;import jakarta.validation.Valid;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.List;
@RestController @RequestMapping("/api/focus-sessions") public class FocusController {private final FocusService service;private final UserRepository users;public FocusController(FocusService s,UserRepository u){service=s;users=u;}private Long uid(Authentication a){return users.findByEmail(a.getName()).orElseThrow().getId();}@GetMapping public List<FocusView> list(Authentication a){return service.list(uid(a));}@PostMapping public FocusView save(Authentication a,@Valid @RequestBody FocusRequest r){return service.save(uid(a),r);}}
